package subsetsum

import "testing"

func TestEmptyZero(t *testing.T) {
	if !SubsetSum([]int{}, 0) {
		t.Errorf("SubsetSum([],0) = false, want true")
	}
}

func TestFoundSimple(t *testing.T) {
	if !SubsetSum([]int{3, 34, 4, 12, 5, 2}, 9) {
		t.Errorf("SubsetSum([3,34,4,12,5,2],9) = false, want true")
	}
}

func TestNotFound(t *testing.T) {
	if SubsetSum([]int{3, 34, 4, 12, 5, 2}, 30) {
		t.Errorf("SubsetSum([3,34,4,12,5,2],30) = true, want false")
	}
}

func TestFoundPair(t *testing.T) {
	if !SubsetSum([]int{1, 5, 3, 11, 12}, 17) {
		t.Errorf("SubsetSum([1,5,3,11,12],17) = false, want true")
	}
}
